const items = $input.all();
const p = items[0]?.json || {};
const l = items[1]?.json || {};
const q = items[2]?.json || {};

const week = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const pctChange = (a, b) => b > 0 ? ((a - b) / b * 100).toFixed(0) + '%' : 'N/A';
const arrow = (a, b) => a >= b ? '▲' : '▼';

const progWoW = pctChange(p.programs_this_week, p.programs_last_week);
const leadWoW = pctChange(l.leads_this_week, l.leads_last_week);

const html = `<!DOCTYPE html><html><body style="font-family:'Helvetica Neue',Arial,sans-serif;background:#0b0f0c;color:#d4ddd6;max-width:680px;margin:0 auto;padding:32px">
<h1 style="color:#7caf58">Deus Performance</h1>
<h2 style="color:#d4ddd6;margin-top:0">Weekly KPI Report — ${week}</h2>
<hr style="border:none;border-top:1px solid #1e2820">

<h3 style="color:#7caf58">Coaching Engine</h3>
<table style="width:100%;border-collapse:collapse">
  <tr><td style="padding:8px 0;border-bottom:1px solid #1e2820">Programs generated (this week)</td><td style="text-align:right;font-weight:700">${p.programs_this_week || 0} <span style="color:#a0a8a2;font-size:12px">${arrow(p.programs_this_week, p.programs_last_week)} ${progWoW} WoW</span></td></tr>
  <tr><td style="padding:8px 0;border-bottom:1px solid #1e2820">Success rate</td><td style="text-align:right;font-weight:700;color:#7caf58">${q.success_pct || 0}%</td></tr>
  <tr><td style="padding:8px 0;border-bottom:1px solid #1e2820">First-pass QC rate</td><td style="text-align:right">${q.first_pass_pct || 0}%</td></tr>
  <tr><td style="padding:8px 0;border-bottom:1px solid #1e2820">Avg LLM attempts</td><td style="text-align:right">${parseFloat(p.avg_attempts || 1).toFixed(2)}</td></tr>
  <tr><td style="padding:8px 0">Retried generations</td><td style="text-align:right">${p.retried_this_week || 0}</td></tr>
</table>

<h3 style="color:#7caf58;margin-top:24px">Leads & Growth</h3>
<table style="width:100%;border-collapse:collapse">
  <tr><td style="padding:8px 0;border-bottom:1px solid #1e2820">New leads (this week)</td><td style="text-align:right;font-weight:700">${l.leads_this_week || 0} <span style="color:#a0a8a2;font-size:12px">${arrow(l.leads_this_week, l.leads_last_week)} ${leadWoW} WoW</span></td></tr>
  <tr><td style="padding:8px 0">Total leads (all-time)</td><td style="text-align:right">${l.total_leads || 0}</td></tr>
</table>

<hr style="border:none;border-top:1px solid #1e2820;margin-top:32px">
<p style="font-size:12px;color:#6b7a6e">Generated automatically by Deus Performance n8n · Riz Management LLC</p>
</body></html>`;

const slackText = `*Deus Performance — Weekly KPIs (${week})*\n>Programs: ${p.programs_this_week || 0} (${arrow(p.programs_this_week, p.programs_last_week)} ${progWoW})\n>Success rate: ${q.success_pct || 0}%  |  First-pass QC: ${q.first_pass_pct || 0}%\n>New leads: ${l.leads_this_week || 0} (${arrow(l.leads_this_week, l.leads_last_week)} ${leadWoW})  |  Total: ${l.total_leads || 0}`;

return [{ json: { html, slackText, week } }];
